public class DuplicateSymbolNameProgramCorrelatorFactory : VTAbstractProgramCorrelatorFactory {

	static readonly string DESC =
		"Compares symbols by iterating over all defined function and data symbols " +
			"meeting the minimum size requirement in the source program and looking " +
			"for identical symbol matches in the destination program. It ignores default " +
			"symbols such as those starting with FUN_, DAT_, s_, and u_. It strips off the " +
			"ending address that is sometimes included on symbols.It reports back " +
			"any that have MORE THAN ONE identical match.";
	static readonly string DUP_SYMBOL_MATCH = "Duplicate Exact Symbol Name Match";

	public static readonly string MIN_SYMBOL_NAME_LENGTH = "Minimum Symbol Name Length";
	public static readonly int MIN_SYMBOL_NAME_LENGTH_DEFAULT = 3;

	public static readonly string INCLUDE_EXTERNAL_SYMBOLS = "Include External Function Symbols";
	public static readonly bool INCLUDE_EXTERNAL_SYMBOLS_DEFAULT = true;

